BEGIN;
ALTER TABLE founder_authorities ADD COLUMN IF NOT EXISTS revoked_at timestamptz;
CREATE OR REPLACE FUNCTION custody_metadata_keys_allowed(j jsonb) RETURNS boolean LANGUAGE sql IMMUTABLE AS $$ SELECT NOT EXISTS (SELECT 1 FROM jsonb_object_keys(j) AS k WHERE k NOT IN ('provider','installation_display_id','scopes','algorithm','key_version','rotation_generation','shape_id','notes')) $$;
ALTER TABLE custody_rows ADD CONSTRAINT custody_metadata_keys CHECK (custody_metadata_keys_allowed(metadata));
CREATE POLICY custody_write ON custody_rows FOR INSERT WITH CHECK (tenant_id=nullif(current_setting('app.tenant_id',true),'')::uuid);
CREATE POLICY reference_write ON minted_references FOR INSERT WITH CHECK (tenant_id=nullif(current_setting('app.tenant_id',true),'')::uuid);
CREATE POLICY audit_write ON custody_audit FOR INSERT WITH CHECK (tenant_id=nullif(current_setting('app.tenant_id',true),'')::uuid);
CREATE OR REPLACE FUNCTION mint_custody_reference(p_credential_class text,p_namespace epr_namespace,p_model custody_model,p_key_locator text,p_metadata jsonb DEFAULT '{}') RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE principal uuid:=nullif(current_setting('app.principal_id',true),'')::uuid;t uuid;p uuid;g founder_authorities%ROWTYPE;row_id uuid:=gen_random_uuid();ref text;ms bigint;hexms text; BEGIN IF principal IS NULL THEN RAISE EXCEPTION 'MINT_AUTHORITY_REFUSED' USING ERRCODE='42501';END IF;SELECT * INTO g FROM founder_authorities WHERE principal_id=principal FOR SHARE;IF NOT FOUND OR g.revoked_at IS NOT NULL OR g.expires_at<=clock_timestamp() OR NOT('custody:mint'=ANY(g.scopes)) THEN RAISE EXCEPTION 'MINT_AUTHORITY_REFUSED' USING ERRCODE='42501';END IF;SELECT tenant_id,project_id INTO t,p FROM project_memberships WHERE principal_id=principal LIMIT 1;IF t IS NULL THEN RAISE EXCEPTION 'TENANT_PROJECT_REFUSED' USING ERRCODE='42501';END IF;IF p_namespace='shape' THEN RAISE EXCEPTION 'NAMESPACE_REFUSED' USING ERRCODE='42501';END IF;IF p_model='B' AND p_key_locator IS NULL THEN RAISE EXCEPTION 'KEY_LOCATOR_REQUIRED';END IF;IF p_model='A' AND p_key_locator IS NOT NULL THEN RAISE EXCEPTION 'KEY_LOCATOR_FORBIDDEN';END IF;ms:=floor(extract(epoch from clock_timestamp())*1000)::bigint;hexms:=lpad(to_hex(ms),12,'0');ref:=format('epr:%s:%s-%s-7%s-8%s-%s',p_namespace,substr(hexms,1,8),substr(hexms,9,4),substr(replace(row_id::text,'-',''),1,3),substr(replace(row_id::text,'-',''),18,3),substr(replace(row_id::text,'-',''),21,12));INSERT INTO custody_rows(id,tenant_id,project_id,namespace,credential_class,custody_model,key_locator,metadata,minted_by_principal_id,retention_policy) VALUES(row_id,t,p,p_namespace,p_credential_class,p_model,p_key_locator,p_metadata,principal,'RET-AUDIT-400');INSERT INTO minted_references VALUES(ref,row_id,t,p,p_namespace,clock_timestamp());INSERT INTO custody_audit(tenant_id,project_id,namespace,credential_class,action,outcome,principal_id,reference) VALUES(t,p,p_namespace,p_credential_class,'mint','success',principal,ref);RETURN ref;EXCEPTION WHEN unique_violation THEN RAISE EXCEPTION 'REFERENCE_COLLISION' USING ERRCODE='23505';END $$;
REVOKE ALL ON FUNCTION mint_custody_reference(text,epr_namespace,custody_model,text,jsonb) FROM PUBLIC,engram_app;GRANT EXECUTE ON FUNCTION mint_custody_reference(text,epr_namespace,custody_model,text,jsonb) TO engram_maintenance;
COMMIT;
